package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.databind.util.Annotations;
import java.io.*;
import java.lang.annotation.Annotation;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.reflect.Proxy;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class AnnotationMap__add_TriageGen1Test {

    private AnnotationMap annotationMap;

    @Before
    public void setUp() {
        annotationMap = new AnnotationMap();
    }

    /**
     * Mock Annotation interface to facilitate testing
     */
    @Retention(RetentionPolicy.RUNTIME)
    @interface TestAnnotation {
        String value() default "default";
    }

    /**
     * Helper to create a proxy for Annotation to control equals() behavior
     */
    private Annotation createMockAnnotation(Class<? extends Annotation> type, Object value) {
        return (Annotation) Proxy.newProxyInstance(
                type.getClassLoader(),
                new Class[]{type},
                (proxy, method, args) -> {
                    if (method.getName().equals("annotationType")) {
                        return type;
                    }
                    if (method.getName().equals("equals")) {
                        Annotation other = (Annotation) args[0];
                        return value.equals(other == null ? null : value); // Simplified for testing logic
                    }
                    if (method.getName().equals("hashCode")) {
                        return value.hashCode();
                    }
                    return null;
                });
    }

    /**
     * Since we cannot easily call a protected method from an external test class 
     * without reflection or a subclass, we use a subclass to expose it.
     */
    private static class TestableAnnotationMap extends AnnotationMap {
        public boolean publicAdd(Annotation ann) {
            return this._add(ann);
        }
    }

    private TestableAnnotationMap testableMap;

    @Before
    public void setUpTestable() {
        testableMap = new TestableAnnotationMap();
    }

    @Test
    public void testAdd_FirstTime() {
        // Test adding an annotation when _annotations is null (first time)
        TestAnnotation ann = createMockAnnotation(TestAnnotation.class, "first");

        // The method returns (previous != null) && previous.equals(ann)
        // Since it's the first time, previous is null, so result should be false
        boolean result = testableMap.publicAdd(ann);

        assertFalse("First add should return false because previous was null", result);
        assertEquals("Size should be 1", 1, testableMap.size());
    }

    @Test
    public void testAdd_DuplicateSameInstance() {
        TestAnnotation ann = createMockAnnotation(TestAnnotation.class, "same");

        // First add
        testableMap.publicAdd(ann);

        // Second add with same instance (previous.equals(ann) will be true)
        boolean result = testableMap.publicAdd(ann);

        assertTrue("Adding same instance again should return true", result);
        assertEquals("Size should still be 1", 1, testableMap.size());
    }

    @Test
    public void testAdd_DifferentAnnotationDifferentType() {
        @Retention(RetentionPolicy.RUNTIME)
        interface AnotherAnnotation {}

        TestAnnotation ann1 = createMockAnnotation(TestAnnotation.class, "val1");
        AnotherAnnotation ann2 = createMockAnnotation(AnotherAnnotation.class, "val2");

        testableMap.publicAdd(ann1);
        boolean result = testableMap.publicAdd(ann2);

        assertFalse("Adding different type should return false (previous is not null, but not equal)", result);
        assertEquals("Size should be 2", 2, testableMap.size());
    }

    @Test
    public void testAdd_SameTypeDifferentContent() {
        @Retention(RetentionPolicy.RUNTIME)
        interface ContentAnnotation { String val(); }

        // We need to simulate an annotation that is NOT equal to the previous one
        // but has the same annotationType()
        ContentAnnotation ann1 = (ContentAnnotation) Proxy.newProxyInstance(
                ContentAnnotation.class.getClassLoader(),
                new Class[]{ContentAnnotation.class},
                (proxy, method, args) -> method.getName().equals("annotationType") ? ContentAnnotation.class : "A");

        ContentAnnotation ann2 = (ContentAnnotation) Proxy.newProxyInstance(
                ContentAnnotation.class.getClassLoader(),
                new Class[]{ContentAnnotation.class},
                (proxy, method, args) -> method.getName().equals("annotationType") ? ContentAnnotation.class : "B");

        // Note: In the real proxy, we must ensure equals() returns false for different content
        // The logic in _add is: (previous != null) && previous.equals(ann)

        testableMap.publicAdd(ann1);

        // To force previous.equals(ann) to be false:
        // We rely on the fact that Proxy objects' default equals is identity-based 
        // unless we override it.
        boolean result = testableMap.publicAdd(ann2);

        assertFalse("Adding different annotation of same type should return false", result);
        assertEquals("Size should be 1 as it replaced the previous one", 1, testableMap.size());
    }
}
